import{_ as a,o as r,c as l,a2 as d}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"النظام القضائي وآلية الفصل في المنازعات","description":"","frontmatter":{},"headers":[],"relativePath":"ar/48-司法体系与裁决机制.md","filePath":"ar/48-司法体系与裁决机制.md","lastUpdated":null}'),i={name:"ar/48-司法体系与裁决机制.md"};function e(o,t,h,n,s,b){return r(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="النظام-القضائي-وآلية-الفصل-في-المنازعات" tabindex="-1">النظام القضائي وآلية الفصل في المنازعات <a class="header-anchor" href="#النظام-القضائي-وآلية-الفصل-في-المنازعات" aria-label="Permalink to &quot;النظام القضائي وآلية الفصل في المنازعات&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>48</td></tr><tr><td>الوحدة</td><td>النظام القانوني وإطار الحوكمة</td></tr><tr><td>الكلمات المفتاحية</td><td>محكمة التكافل، الفصل المستقل، الفصل متعدد الأعراق، الفصل في قضايا الزراعة، التسوية البديلة للنزاعات</td></tr></tbody></table><h2 id="أولاً-نظرة-عامة-على-النظام-القضائي" tabindex="-1">أولاً: نظرة عامة على النظام القضائي <a class="header-anchor" href="#أولاً-نظرة-عامة-على-النظام-القضائي" aria-label="Permalink to &quot;أولاً: نظرة عامة على النظام القضائي&quot;">​</a></h2><p>النظام القضائي في حضارة التكافل المرساة جزء مهم من «فصل وتوازن السلطات الثلاث». تمارس محكمة التكافل سلطة الفصل بشكل مستقل وفقاً للقانون، وتفصل في المنازعات بين جميع الكائنات داخل كون هنغ يوان، وتحرس العدالة وتحافظ على نظام سيادة القانون التكافلي.</p><p>يتبع النظام القضائي المبادئ الأساسية التالية:</p><table tabindex="0"><thead><tr><th>المبدأ</th><th>المضمون</th></tr></thead><tbody><tr><td>الفصل المستقل</td><td>تمارس المحكمة سلطة الفصل بشكل مستقل وفقاً للقانون؛ ولا يجوز لأي منظمة أو فرد التدخل</td></tr><tr><td>الفصل العادل</td><td>تُفصل القضايا على أساس الوقائع والقانون؛ والحماية المتساوية للحقوق والمصالح المشروعة لجميع الأطراف</td></tr><tr><td>المحاكمة العلنية</td><td>أنشطة الفصل علنية للجمهور، باستثناء القضايا المتعلقة بأسرار الدولة وخصوصية الحياة والأسرار التجارية</td></tr><tr><td>درجتا تقاضٍ</td><td>تخضع القضايا لنظام نهائي من درجتين؛ وتُقبل استئناف واحد لقضايا الدرجة الأولى</td></tr><tr><td>حماية حقوق التقاضي</td><td>للأطراف حق التقاضي والدفاع والاستئناف وطلب إعادة النظر</td></tr><tr><td>المشاركة متعددة الأعراق</td><td>يشارك ممثلو جميع الأعراق في الفصل، لضمان تكيف الفصل مع الخصائص الفسيولوجية والثقافية لجميع الأعراق</td></tr></tbody></table><h2 id="ثانياً-هيكل-المحاكم-واختصاصاتها" tabindex="-1">ثانياً: هيكل المحاكم واختصاصاتها <a class="header-anchor" href="#ثانياً-هيكل-المحاكم-واختصاصاتها" aria-label="Permalink to &quot;ثانياً: هيكل المحاكم واختصاصاتها&quot;">​</a></h2><p>تنقسم محكمة التكافل إلى مستويات متعددة، مع تقسيمات اختصاص مناظرة:</p><table tabindex="0"><thead><tr><th>مستوى المحكمة</th><th>الاسم</th><th>الاختصاص</th></tr></thead><tbody><tr><td>الدرجة الأولى</td><td>محكمة المجتمع</td><td>المنازعات المدنية البسيطة، المنازعات البسيطة بين السكان، منازعات العمل، منازعات المستهلك</td></tr><tr><td>الدرجة الثانية</td><td>المحكمة الإقليمية</td><td>القضايا المدنية والتجارية والزراعية والإدارية ذات الأهمية العادية</td></tr><tr><td>الدرجة الثالثة</td><td>المحكمة العليا للتكافل</td><td>القضايا الكبرى والمعقدة، القضايا الدستورية، القضايا العابرة للأبعاد، القضايا متعددة الأعراق</td></tr><tr><td>متخصصة</td><td>المحكمة الزراعية المتخصصة</td><td>قضايا الزراعة: انحراف الزراعة، الارتداد الطاقي، تآكل القوانين، منازعات الطوائف، منازعات موارد الزراعة</td></tr><tr><td>متخصصة</td><td>محكمة مجال الوعي</td><td>القضايا المتعلقة بمجال الوعي، التلوث الروحي، الجرائم المعلوماتية</td></tr><tr><td>متخصصة</td><td>المحكمة العسكرية</td><td>قضايا العسكريين وأنشطة الزراعة المرتبطة بالجيش</td></tr></tbody></table><p>تتمتع المحكمة العليا للتكافل أيضاً بوظائف توحيد تفسير القانون وإصدار التفسيرات القضائية والإشراف على المحاكم الأدنى.</p><h2 id="ثالثاً-آلية-الفصل" tabindex="-1">ثالثاً: آلية الفصل <a class="header-anchor" href="#ثالثاً-آلية-الفصل" aria-label="Permalink to &quot;ثالثاً: آلية الفصل&quot;">​</a></h2><h3 id="أ-نظام-الفصل-متعدد-الأعراق" tabindex="-1">(أ) نظام الفصل متعدد الأعراق <a class="header-anchor" href="#أ-نظام-الفصل-متعدد-الأعراق" aria-label="Permalink to &quot;(أ) نظام الفصل متعدد الأعراق&quot;">​</a></h3><p>بالنسبة للقضايا المتعلقة بأعراق خاصة، يُطبق نظام الفصل متعدد الأعراق:</p><ol><li>تشمل القضايا المتعلقة بعرق واحد محكمين من ذلك العرق في الهيئة الجماعية.</li><li>تشمل القضايا متعددة الأعراق محكمين من الأعراق المعنية؛ وتُحدد تركيبة الهيئة وفق عدد وتعقيد الأعراق المعنية.</li><li>بالنسبة للقضايا ذات الخصائص الفسيولوجية الخاصة (مثل الأعراق المائية والكائنات الطاقية)، يمكن دعوة خبراء خاصين للمشاركة في الفصل.</li><li>تُحدد مسائل الأدلة والوقائع المتعلقة بعادات الأعراق بالرجوع إلى القوانين العرفية للأعراق المعنية.</li></ol><h3 id="ب-الفصل-في-قضايا-الزراعة" tabindex="-1">(ب) الفصل في قضايا الزراعة <a class="header-anchor" href="#ب-الفصل-في-قضايا-الزراعة" aria-label="Permalink to &quot;(ب) الفصل في قضايا الزراعة&quot;">​</a></h3><p>تتميز قضايا الزراعة بدرجة تقنية عالية؛ وتشمل آلية الفصل في قضايا الزراعة:</p><ol><li><strong>المحكمون الخبراء في الزراعة</strong>: تشمل القضايا المتعلقة بالمسائل المهنية مثل انحراف الزراعة والارتداد الطاقي وتآكل القوانين خبراء في الزراعة كمحكمين.</li><li><strong>تحديد أدلة المستوى</strong>: يعتمد تحديد مستوى وقوة المزارع على مؤسسات الاختبار والخبرة المعيارية.</li><li><strong>تطبيق قانون الزراعة</strong>: يطبق الفصل في قضايا الزراعة قوانين وتقنيات الزراعة، بالجمع بين الأحكام القانونية والحس الزراعي العام.</li><li><strong>التنفيذ الخاص</strong>: يمكن أن يستخدم تنفيذ الأحكام في قضايا الزراعة وسائل مثل القيود الطاقية والمحظورات الروحية.</li></ol><h3 id="ج-نظام-الوساطة" tabindex="-1">(ج) نظام الوساطة <a class="header-anchor" href="#ج-نظام-الوساطة" aria-label="Permalink to &quot;(ج) نظام الوساطة&quot;">​</a></h3><p>تعزز المحكمة نظام الوساطة، وتشجع الأطراف على تسوية النزاعات عبر الوساطة:</p><ul><li><strong>الوساطة قبل التقاضي</strong>: بالنسبة للنزاعات البسيطة، تُشجع الوساطة قبل التقاضي.</li><li><strong>الوساطة القضائية</strong>: أثناء إجراءات المحاكمة، وبموافقة الأطراف، يمكن للمحكمة إجراء الوساطة.</li><li><strong>الوساطة ذات الطابع العرقي</strong>: تحترم الوساطة عادات وتقاليد جميع الأعراق؛ ويمكن لكبار الأعراق أو ممثلي الأقليات المشاركة في الوساطة.</li><li><strong>أثر الوساطة</strong>: اتفاقية الوساطة ذات الأثر القانوني ملزمة؛ وعند عدم التنفيذ يمكن طلب التنفيذ.</li></ul><h3 id="د-التسوية-البديلة-للنزاعات" tabindex="-1">(د) التسوية البديلة للنزاعات <a class="header-anchor" href="#د-التسوية-البديلة-للنزاعات" aria-label="Permalink to &quot;(د) التسوية البديلة للنزاعات&quot;">​</a></h3><p>إلى جانب التقاضي، تُنشأ طرق التسوية البديلة التالية للنزاعات:</p><table tabindex="0"><thead><tr><th>الطريقة</th><th>المضمون</th></tr></thead><tbody><tr><td>التحكيم</td><td>النزاعات المتفق على تحكيمها تُحسم بجهة التحكيم؛ وقرار التحكيم نهائي</td></tr><tr><td>التحديد الخبير</td><td>يمكن تحديد النزاعات المهنية من مؤسسات الخبراء</td></tr><tr><td>التشاور التكافلي</td><td>تُحسم النزاعات بين الأعراق أو المنظمات عبر آلية التشاور التكافلية</td></tr><tr><td>وساطة الكبار</td><td>بالنسبة للنزاعات التقليدية للأعراق الخاصة، يمكن اعتماد وساطة كبار الأعراق</td></tr></tbody></table><h2 id="رابعاً-نظام-التقاضي" tabindex="-1">رابعاً: نظام التقاضي <a class="header-anchor" href="#رابعاً-نظام-التقاضي" aria-label="Permalink to &quot;رابعاً: نظام التقاضي&quot;">​</a></h2><h3 id="أ-أهلية-المدعي" tabindex="-1">(أ) أهلية المدعي <a class="header-anchor" href="#أ-أهلية-المدعي" aria-label="Permalink to &quot;(أ) أهلية المدعي&quot;">​</a></h3><p>يحق للأطراف التالية رفع الدعاوى:</p><ul><li>الكائنات الطبيعية والأطراف التنظيمية التي أُصيبت حقوقها ومصالحها المشروعة</li><li>يمكن لمكتب الادعاء التكافلي رفع دعاوى عامة عن الأفعال الضارة بالمصالح العامة</li><li>يمكن لمنظمات المنفعة العامة المحددة قانوناً رفع دعاوى عامة ضمن مجالاتها</li></ul><h3 id="ب-نظام-الأدلة" tabindex="-1">(ب) نظام الأدلة <a class="header-anchor" href="#ب-نظام-الأدلة" aria-label="Permalink to &quot;(ب) نظام الأدلة&quot;">​</a></h3><p>يشمل نظام الأدلة في محكمة التكافل:</p><ol><li><strong>أنواع الأدلة</strong>: الأدلة المادية، الأدلة المستندية، شهادات الشهود، أقوال الأطراف، آراء الخبرة، محاضر التفتيش، أدلة مجال الوعي وغيرها.</li><li><strong>عبء الإثبات</strong>: يتحمل المدعي عبء إثبات مطالباته؛ والطرف الذي يدعي واقعاً لصالحه يتحمل عبء إثبات تلك الواقعة.</li><li><strong>الأدلة الطاقية</strong>: الأدلة المستخرجة من مجال الوعي والآثار الطاقية يجب أن يستخرجها جهات مصرح بها قانوناً لضمان الشرعية والصدق.</li><li><strong>الأدلة عبر الأبعاد</strong>: الأدلة المتعلقة بأبعاد متعددة يُعترف بها ويُحوَّل بينها عبر آلية التعاون القضائي عبر الأبعاد.</li></ol><h3 id="ج-نظام-التنفيذ" tabindex="-1">(ج) نظام التنفيذ <a class="header-anchor" href="#ج-نظام-التنفيذ" aria-label="Permalink to &quot;(ج) نظام التنفيذ&quot;">​</a></h3><p>الأحكام والقرارات ذات الأثر القانوني واجبة التنفيذ. وبالنسبة للممتنعين عن التنفيذ، يمكن للمحكمة اتخاذ إجراءات التنفيذ التالية:</p><ul><li>تجميد ونقل موارد الزراعة والممتلكات</li><li>القيود الطاقية والقيود الزراعية</li><li>الإعلان العلني عن السلوك غير النزيه</li><li>الاحتجاز وغيرها من الإجراءات الجبرية (في الحالات الجسيمة)</li></ul><h2 id="خامساً-الرقابة-القضائية" tabindex="-1">خامساً: الرقابة القضائية <a class="header-anchor" href="#خامساً-الرقابة-القضائية" aria-label="Permalink to &quot;خامساً: الرقابة القضائية&quot;">​</a></h2><p>لضمان العدالة القضائية، تُنشأ آليات الرقابة التالية:</p><ul><li><strong>رقابة لجنة الرقابة للمرساة</strong>: تشرف لجنة الرقابة للمرساة على الأنشطة القضائية وفقاً للقانون، وتضمن عمل الأجهزة القضائية بشكل قانوني.</li><li><strong>رقابة الدرجة الثانية وإعادة النظر</strong>: تصحح منظومة الاستئناف ومنظومة إعادة النظر الأحكام الخاطئة الصادرة من الدرجة الأولى.</li><li><strong>الرقابة التأديبية</strong>: يخضع القضاة المخالفون للانضباط للمساءلة التأديبية.</li><li><strong>الرقابة الاجتماعية</strong>: يشرف الجمهور على الأنشطة القضائية عبر حضور المحاكمات والرأي العام وغيرها.</li></ul><h2 id="سادساً-التعاون-القضائي-عبر-الأبعاد" tabindex="-1">سادساً: التعاون القضائي عبر الأبعاد <a class="header-anchor" href="#سادساً-التعاون-القضائي-عبر-الأبعاد" aria-label="Permalink to &quot;سادساً: التعاون القضائي عبر الأبعاد&quot;">​</a></h2><p>بالنسبة للقضايا العابرة للأبعاد، يُنشأ آلية التعاون القضائي:</p><ol><li>الاعتراف المتبادل بالأحكام بين الأبعاد.</li><li>المساعدة عبر الأبعاد في التبليغ والأدلة.</li><li>التعاون القضائي الجنائي عبر الأبعاد.</li><li>المساعدة عبر الأبعاد في التنفيذ وتبادل معلومات السلوك غير النزيه.</li></ol><h2 id="الخاتمة" tabindex="-1">الخاتمة <a class="header-anchor" href="#الخاتمة" aria-label="Permalink to &quot;الخاتمة&quot;">​</a></h2><p><em>النظام القضائي وآلية الفصل في المنازعات</em> هو خط الدفاع الأخير لنظام سيادة القانون في حضارة التكافل المرساة. بإنشاء نظام محاكم متعدد المستويات، ونظام الفصل متعدد الأعراق، وآلية الفصل في قضايا الزراعة، يضمن عدالة الفصل وسلطانه، ويحرس الحقوق والمصالح المشروعة لجميع الكائنات، ويوفر ضمانات قضائية قوية لتقدم عشرة آلاف عرق معاً.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>40-共生宪法总纲 (الدستور التكافلي: المبادئ العامة)</li><li>49-治理框架与权力制衡 (إطار الحوكمة وتوازن السلطات)</li><li>44-医疗保障法 (قانون ضمان الرعاية الصحية)</li><li>30-锚点议事会职能与议事规则 (وظائف وقواعد عمل المجلس التشريعي للمرساة)</li></ul>',43)])])}const p=a(i,[["render",e]]);export{c as __pageData,p as default};
